head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
scwin.vScrenID = 'ULDBNS05502.xml';
scwin.vMktactCd = "320";
scwin.pBndApplId = '';
scwin.pBndListProcsTpCd = '2';
scwin.vModInfoRowCount = 0, scwin.vChkDuplRowCount = 0;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : fn_SetParam
 * 설명       : 부모창에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParam = function() {
    var prt = $c.frame.path("../");
    if (prt != undefined) {
        scwin.fn_GetPar = prt.scwin.fn_GetPar;
        scwin.fn_SetPar = prt.scwin.fn_SetPar;
    }
    if (scwin.fn_GetPar != undefined) {
        var arrPar = new Array();
        scwin.fn_GetPar(arrPar);
        scwin.pBndApplId = arrPar[1].BND_APPL_ID;
        scwin.pBndListProcsTpCd = arrPar[1].BND_LIST_PROCS_TP_CD;
    }
};



/********************************************** 
 * 함수명   : fn_InputCheck
 * 설명      : 필수 입력 값을 체크한다. 
 ***********************************************/
scwin.fn_InputCheck = function() {
    if ($c.stf.getObjectValue(edt_StrtDd) == '') {
        $c.win.alert("[적용일]을 입력하십시오.");
        edt_StrtDd.focus();
        return false;
    }

    //적용일,매매일,마감일,채권마감 체크		
    if ($c.bns.fn_CheckCmData(scwin.vScrenID, dts_CheckCmData, $c.stf.getObjectValue(edt_StrtDd), scwin.pBndApplId) > 0) return false;
    if ($c.stf.getObjectValue(edt_SaleDd) == '') {
        $c.win.alert("[매출일]을 입력하십시오.");
        edt_SaleDd.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_BndSaleTotamt) == '') {
        $c.win.alert("[일중 매출총액]을 입력하십시오.");
        edt_BndSaleTotamt.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_RedmptAmt) == '') {
        $c.win.alert("[일중 중도상환액]을 입력하십시오.");
        edt_RedmptAmt.focus();
        return false;
    }
    if (scwin.vChkDuplRowCount > 1) {
        $c.win.alert("동일종목에 대하여 적용일이 다른 접수내역이 있습니다.\n각 접수내역의 적용일을 일치시켜 주시기 바랍니다.");
    }
    return true;
};


/********************************************** 
 * 함수명   : fn_update
 * 설명      : 접수내역 수정
 ***********************************************/
scwin.fn_update = function() {
    if (scwin.fn_InputCheck() == false) return;
    var url = "/bns/IsuChgAmt.do?method=updateAcpt";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    url += "&MKTACT_TP_CD=" + scwin.vMktactCd;
    dts_ModInfo.UseChangeInfo = "False";
    trs_Update.Action = $c.lc.fn_encodeNSession(url);
    trs_Update.KeyName = "toinb_dataid4";
    trs_Update.KeyValue = "JSP(I:pInput=dts_ModInfo)";
    trs_Update.Post();
};


//일별금액조정 시 동일종목에 대한 적용일이 다른 접수내역에 있는지 체크
scwin.fn_dupl_cnt = function() {
    var url = "/listingCommon.do?method=listGeneralForDynamicName";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=BNS_CHECK_ACPT_DUPL";
    url += "&queryId=lds.stf.bnsisuchg.select.checkAcptDupl";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_ISU_CD=" + dts_ModInfo.getCellData(1, "ISU_CD");
    dts_CheckDupl.SyncLoad = "true";
    dts_CheckDupl.DataID = encodeURI(url);
    dts_CheckDupl.Reset();
};
scwin.gform_onload = function() {
    //패널라운드처리
    $c.bns.BnsPanelToGroupBox(pnl_Item);

    //호출파라미터설정
    scwin.fn_SetParam();

    //일별매출내역신고수정(일별금액조정) 조회
    var url = "/listingCommon.do?method=listGeneralForDynamicName";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=BNS_DAY_SALES_UPDATE_INFO";
    url += "&queryId=lds.stf.bnsisuchg.select.listAcptUpdateListPop";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_BND_LIST_PROCS_TP_CD=" + scwin.pBndListProcsTpCd;
    url += "&{P}V_BND_APPL_ID=" + scwin.pBndApplId;
    dts_ModInfo.DataID = encodeURI(url);
    dts_ModInfo.reset();
};
scwin.dts_ModInfo_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_ModInfo_OnLoadCompleted = function(rowcount) {
    scwin.vModInfoRowCount = rowcount;
    scwin.fn_dupl_cnt();

    //매출초일여부 체크 설정
    if (dts_ModInfo.getCellData(1, "FST_SALE_DD_YN") == 'Y') {
        chk_FstSaleDdYn.setValue(1);
    } else {
        chk_FstSaleDdYn.setValue(0);
    }
    edt_BndSaleTotamt.RightMargin = 5;
    edt_RedmptAmt.RightMargin = 5;
};
scwin.dts_CheckDupl_OnLoadCompleted = function(rowcount) {
    scwin.vChkDuplRowCount = dts_CheckDupl.getCellData(1, "TEXT");
};
scwin.img_StrtDd_onclick = function() {
    if (scwin.vModInfoRowCount == 0) return;
    popUpCalendar2(edt_StrtDd);
};
scwin.img_Saledd_onclick = function() {
    if (scwin.vModInfoRowCount == 0) return;
    popUpCalendar2(edt_SaleDd);
};
scwin.btn_Mod_onclick = function() {
    if (scwin.vModInfoRowCount == 0) return;
    scwin.fn_update();
};
scwin.trs_Update_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "수정"));
};
scwin.trs_Update_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "수정"));
    var arrPar = new Array();
    arrPar[0] = {
        SUCCESS_YN: 'Y',
        STRT_DD: $c.stf.getObjectValue(edt_StrtDd)
    };
    var parentFrame = $c.frame.path("../");
    scwin.fn_SetPar = parentFrame.fn_SetReturnMod;
    scwin.fn_SetPar(arrPar);
    await $c.frame.CloseFrame();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.edt_BndSaleTotamt_OnKillFocus = function() {
    edt_BndSaleTotamt.RightMargin = 5;
};
scwin.edt_RedmptAmt_OnKillFocus = function() {
    edt_RedmptAmt.RightMargin = 5;
};
